/**
 * A scheduled job. Jobs are created via Scheduler.every(interval) and
 * registered with the scheduler once .do(fn) is called. Time units are
 * fluent no-ops — no actual timers are involved.
 *
 * This module deliberately does NOT import scheduler.mjs; it only uses the
 * scheduler object passed to the constructor (avoids circular imports).
 */
export class Job {
  constructor(scheduler, interval) {
    this.scheduler = scheduler;
    this.interval = interval;
    this.unit = null;
    this.tags = new Set();
    this.jobFunc = null;
  }

  /** Fluent unit setters; return this for chaining. */
  get seconds() {
    this.unit = 'seconds';
    return this;
  }

  get minutes() {
    this.unit = 'minutes';
    return this;
  }

  /** Add one or more string tags to this job. */
  tag(...names) {
    for (const name of names) {
      this.tags.add(name);
    }
    return this;
  }

  /** Register the job's function and append the job to the scheduler. */
  do(fn) {
    this.jobFunc = fn;
    this.scheduler.jobs.push(this);
    return this;
  }
}

