import { Job } from './job.mjs';

/**
 * Minimal port of Python's `schedule` library semantics needed here:
 * jobs are registered into a plain `jobs` array, tags are plain strings
 * stored per job, and no real timing takes place.
 */
export class Scheduler {
  constructor() {
    this.jobs = [];
  }

  /** Create a new Job for the given interval (not yet registered). */
  every(interval) {
    return new Job(this, interval);
  }

  /** Return all jobs, or only jobs carrying the given tag. */
  getJobs(tag) {
    if (tag === undefined) {
      return this.jobs.slice();
    }
    return this.jobs.filter((job) => job.tags.has(tag));
  }

  /** Remove jobs carrying the given tag, or all jobs if tag is omitted. */
  clear(tag) {
    if (tag === undefined) {
      this.jobs.length = 0;
      return;
    }
    this.jobs = this.jobs.filter((job) => !job.tags.has(tag));
  }
}

/** Shared default scheduler, mirroring `schedule`'s module-level API. */
export const defaultScheduler = new Scheduler();

/** Convenience wrappers bound to the default scheduler. */
export function every(interval) {
  return defaultScheduler.every(interval);
}

export function getJobs(tag) {
  return defaultScheduler.getJobs(tag);
}

export function clear(tag) {
  return defaultScheduler.clear(tag);
}

