// test11.mjs — entry point mirroring the original Python script.
// Schedules tagged jobs, then reports job counts through a series of
// queries and clears against the default scheduler.

import { every, getJobs, clear } from './lib/scheduler.mjs';
import { parseArgs } from './lib/argparse.mjs';

const { a, b } = parseArgs(process.argv.slice(2));

// Total jobs created so far; shared across both scheduling loops below.
let jobs_created = 0;

// (1) schedule `a` one-second jobs tagged 'group1' (no-op if a <= 0)
for (let i = 0; i < a; i++) {
  every(1).seconds.tag('group1').do(() => {});
  jobs_created++;
}
console.log(jobs_created);

// (2) schedule `b` one-minute jobs tagged 'group2' (cumulative count)
for (let i = 0; i < b; i++) {
  every(1).minutes.tag('group2').do(() => {});
  jobs_created++;
}
console.log(jobs_created);

// (3)(4)(5) job counts by tag, then overall
console.log(getJobs('group1').length);
console.log(getJobs('group2').length);
console.log(getJobs().length);

// (6) clear 'group1', report remaining
clear('group1');
console.log(getJobs().length);

// (7) clear 'group2', report remaining
clear('group2');
console.log(getJobs().length);

// (8) schedule a+b untagged one-second jobs, report total
for (let i = 0; i < a + b; i++) {
  every(1).seconds.do(() => {});
}
console.log(getJobs().length);

