// Minimal argument parser mimicking Python's argparse for this CLI:
// two required integer options (--a, --b) plus the automatic -h/--help.
import { basename } from 'node:path';

// Tokens starting with '-' are only treated as values when they look like
// negative numbers (same regex argparse uses).
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

// Python int() accepts surrounding whitespace, an optional sign, and
// underscores between digits (e.g. '1_0' == 10).
const INT_PATTERN = /^\s*[+-]?\d+(?:_\d+)*$/;

// Long options known to the parser, in definition order.
const LONG_OPTIONS = ['--help', '--a', '--b'];

function prog() {
  return basename(process.argv[1]);
}

function usage() {
  return `usage: ${prog()} [-h] --a A --b B`;
}

// Print usage + error to stderr and exit like argparse does (code 2).
function error(message) {
  process.stderr.write(`${usage()}\n${prog()}: error: ${message}\n`);
  process.exit(2);
}

function printHelp() {
  const lines = [
    usage(),
    '',
    'options:',
    '  -h, --help  show this help message and exit',
    '  --a A',
    '  --b B',
  ];
  process.stdout.write(lines.join('\n') + '\n');
  process.exit(0);
}

// Convert with Python int() semantics; errors out on invalid values.
function toInt(value, option) {
  if (!INT_PATTERN.test(value)) {
    error(`argument ${option}: invalid int value: '${value}'`);
  }
  return parseInt(value.replace(/_/g, ''), 10);
}

// Resolve a possibly abbreviated long option name, or null if unknown.
function resolveLong(name) {
  if (LONG_OPTIONS.includes(name)) return name;
  const matches = LONG_OPTIONS.filter((o) => o.startsWith(name));
  if (matches.length === 1) return matches[0];
  if (matches.length > 1) {
    error(`ambiguous option: ${name} could match ${matches.join(', ')}`);
  }
  return null;
}

// Parse argv (process.argv.slice(2)) into { a, b } integers.
export function parseArgs(argv) {
  const values = {};
  const extras = [];
  let positionalOnly = false;

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];

    if (positionalOnly) {
      extras.push(arg);
      continue;
    }

    // '--' separates options from positionals (which are all extras here).
    if (arg === '--') {
      positionalOnly = true;
      continue;
    }

    if (arg === '-h') {
      printHelp();
    }

    if (arg.startsWith('--')) {
      // Support both '--opt value' and '--opt=value'.
      let name = arg;
      let inlineValue;
      const eq = arg.indexOf('=');
      if (eq !== -1) {
        name = arg.slice(0, eq);
        inlineValue = arg.slice(eq + 1);
      }

      const option = resolveLong(name);
      if (option === null) {
        extras.push(arg);
        continue;
      }
      if (option === '--help') {
        printHelp();
      }

      let value;
      if (inlineValue !== undefined) {
        value = inlineValue;
      } else {
        const next = argv[i + 1];
        const looksLikeOption =
          next !== undefined &&
          next !== '-' &&
          next.startsWith('-') &&
          !NEGATIVE_NUMBER.test(next);
        if (next === undefined || looksLikeOption) {
          error(`argument ${option}: expected one argument`);
        }
        value = next;
        i++;
      }

      // Type conversion happens immediately, as in argparse.
      values[option] = toInt(value, option);
      continue;
    }

    // Anything else (positionals, unknown short options) is unrecognized.
    extras.push(arg);
  }

  // Required-argument check runs before the unrecognized-arguments check.
  const missing = [];
  if (!('--a' in values)) missing.push('--a');
  if (!('--b' in values)) missing.push('--b');
  if (missing.length > 0) {
    error(`the following arguments are required: ${missing.join(' ')}`);
  }

  if (extras.length > 0) {
    error(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return { a: values['--a'], b: values['--b'] };
}

